<?php
namespace App\Http\Controllers;
use App\Models\Produk; use App\Models\Kategori; use App\Models\FotoProduk; use Illuminate\Http\Request; use App\Helpers\ImageHelper;
class ProdukController extends Controller {
 public function index(Request $request){$q=Produk::with(['kategori','user']);if($request->filled('q'))$q->where('nama_produk','like','%'.$request->q.'%');return view('backend.v_produk.index',['judul'=>'Manajemen Produk','index'=>$q->latest()->paginate(10)->withQueryString()]);}
 public function create(){return view('backend.v_produk.create',['judul'=>'Tambah Produk','kategori'=>Kategori::orderBy('nama_kategori')->get()]);}
 public function store(Request $request){$data=$request->validate(['kategori_id'=>'required|exists:kategori,id','nama_produk'=>'required|max:255','detail'=>'nullable|string','harga'=>'required|numeric|min:0','stok'=>'required|integer|min:0','foto'=>'nullable|image|mimes:jpg,jpeg,png,gif,webp|max:2048']);$data['user_id']=auth()->id();if($request->hasFile('foto')){$name=uniqid('produk_').'.'.$request->file('foto')->extension();ImageHelper::uploadAndResize($request->file('foto'),'img-produk',$name,1200);$data['foto']=$name;}$produk=Produk::create($data);return redirect()->route('backend.produk.show',$produk->id)->with('success','Produk berhasil ditambahkan.');}
 public function show(string $id){return view('backend.v_produk.show',['judul'=>'Detail Produk','produk'=>Produk::with(['kategori','user','fotoProduk'])->findOrFail($id)]);}
 public function edit(string $id){return view('backend.v_produk.edit',['judul'=>'Edit Produk','edit'=>Produk::findOrFail($id),'kategori'=>Kategori::orderBy('nama_kategori')->get()]);}
 public function update(Request $request,string $id){$produk=Produk::findOrFail($id);$data=$request->validate(['kategori_id'=>'required|exists:kategori,id','nama_produk'=>'required|max:255','detail'=>'nullable|string','harga'=>'required|numeric|min:0','stok'=>'required|integer|min:0','foto'=>'nullable|image|mimes:jpg,jpeg,png,gif,webp|max:2048']);if($request->hasFile('foto')){ImageHelper::delete('img-produk',$produk->foto);$name=uniqid('produk_').'.'.$request->file('foto')->extension();ImageHelper::uploadAndResize($request->file('foto'),'img-produk',$name,1200);$data['foto']=$name;}$produk->update($data);return redirect()->route('backend.produk.index')->with('success','Produk berhasil diperbarui.');}
 public function destroy(string $id){$produk=Produk::with('fotoProduk')->findOrFail($id);ImageHelper::delete('img-produk',$produk->foto);foreach($produk->fotoProduk as $foto){ImageHelper::delete('img-produk',$foto->foto);$foto->delete();}$produk->delete();return redirect()->route('backend.produk.index')->with('success','Produk berhasil dihapus.');}
 public function storeFoto(Request $request){$data=$request->validate(['produk_id'=>'required|exists:produk,id','foto_produk'=>'required|array','foto_produk.*'=>'image|mimes:jpg,jpeg,png,gif,webp|max:2048']);foreach($request->file('foto_produk') as $file){$name=uniqid('galeri_').'.'.$file->extension();ImageHelper::uploadAndResize($file,'img-produk',$name,1200);FotoProduk::create(['produk_id'=>$data['produk_id'],'foto'=>$name]);}return redirect()->route('backend.produk.show',$data['produk_id'])->with('success','Foto galeri berhasil ditambahkan.');}
 public function destroyFoto(string $id){$foto=FotoProduk::findOrFail($id);$pid=$foto->produk_id;ImageHelper::delete('img-produk',$foto->foto);$foto->delete();return redirect()->route('backend.produk.show',$pid)->with('success','Foto galeri dihapus.');}
 public function formProduk(){return view('backend.v_produk.form',['judul'=>'Laporan Produk']);}
 public function cetakProduk(Request $request){$data=$request->validate(['tanggal_awal'=>'required|date','tanggal_akhir'=>'required|date|after_or_equal:tanggal_awal']);$items=Produk::with(['kategori','user'])->whereBetween('created_at',[$data['tanggal_awal'].' 00:00:00',$data['tanggal_akhir'].' 23:59:59'])->orderByDesc('id')->get();return view('backend.v_produk.cetak',['judul'=>'Laporan Produk','tanggalAwal'=>$data['tanggal_awal'],'tanggalAkhir'=>$data['tanggal_akhir'],'cetak'=>$items]);}
}
